import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const freezeSpinners = `
  const style = document.createElement("style");
  style.textContent = ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }";
  document.head.appendChild(style);
`;

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".css")) return "text/css";
  if (filePath.endsWith(".html")) return "text/html";
  if (filePath.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 12, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const { port } = server.address();
const origin = `http://127.0.0.1:${port}`;

const browser = await chromium.launch({ executablePath: chrome, headless: true });

try {
  const fixturePage = await browser.newPage({ viewport: { width: 860, height: 1480 }, deviceScaleFactor: 1 });
  await fixturePage.goto(pathToFileURL(path.join(usability, "mobile-sidebar-loading.html")).href, { waitUntil: "load" });
  await fixturePage.screenshot({ path: path.join(usability, "mobile-sidebar-loading.png"), fullPage: true });

  const live = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await live.goto(origin, { waitUntil: "load" });
  await live.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await live.evaluate((script) => { eval(script); }, freezeSpinners);
  await live.selectOption("#traceSelect", "1");
  await live.click("#loadBtn");
  await live.waitForSelector("#traceLoadingHud.visible");
  await live.waitForTimeout(250);
  const metrics = await live.evaluate(() => {
    const sidebar = document.getElementById("sidebar");
    const hud = document.getElementById("traceLoadingHud");
    const statusIndices = document.getElementById("statusIndices");
    const statusGrid = document.getElementById("statusGrid");
    const canvas = document.getElementById("canvasContainer");
    const cs = getComputedStyle(sidebar);
    return {
      innerWidth: window.innerWidth,
      playbackReady: document.body.classList.contains("playback-ready"),
      traceLoading: document.body.classList.contains("trace-loading"),
      loadedMobile: document.body.classList.contains("trace-loaded-mobile"),
      sidebarDisplay: cs.display,
      sidebarHeight: sidebar.getBoundingClientRect().height,
      hudVisible: hud.classList.contains("visible"),
      statusText: `${statusIndices.textContent} | ${statusGrid.textContent}`.replace(/\s+/g, " ").trim(),
      canvasHeight: canvas.getBoundingClientRect().height,
    };
  });
  await live.screenshot({ path: path.join(usability, "mobile-sidebar-loading-live.png") });
  console.log(JSON.stringify(metrics, null, 2));
} finally {
  await browser.close();
  server.close();
}

