import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const usability = path.join(root, "usability");
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

const headerLine = JSON.stringify({
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 10,
  r_val: 20,
  expected_frechet: 1.2,
  bbox: [0, 0, 100, 100],
  stream: [[0, 0], [10, 10], [20, 5]],
}) + "\n";

let pendingTrace = null;

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".html")) return "text/html";
  return "application/octet-stream";
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 12, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    pendingTrace = res;
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

function freeze(page) {
  return page.addStyleTag({
    content: ".button-spinner, .params-spinner { animation: none !important; transform: rotate(40deg); }",
  });
}

async function snapshot(page) {
  return page.evaluate(() => {
    const sidebar = document.getElementById("sidebar");
    const hud = document.getElementById("traceLoadingHud");
    const dock = document.getElementById("mobileTransport");
    const overflow = [];
    const vw = document.documentElement.clientWidth;
    for (const el of document.body.querySelectorAll("*")) {
      const r = el.getBoundingClientRect();
      if (r.width > 1 && r.right > vw + 1) {
        overflow.push({
          id: el.id || el.className?.toString?.().slice(0, 40),
          right: Math.round(r.right),
        });
      }
    }
    return {
      innerWidth: window.innerWidth,
      scrollWidth: document.documentElement.scrollWidth,
      playbackReady: document.body.classList.contains("playback-ready"),
      traceLoading: document.body.classList.contains("trace-loading"),
      loadedMobile: document.body.classList.contains("trace-loaded-mobile"),
      sidebarDisplay: getComputedStyle(sidebar).display,
      sidebarHeight: Math.round(sidebar.getBoundingClientRect().height),
      hudVisible: hud.classList.contains("visible"),
      dockVisible: dock.classList.contains("visible"),
      statusText: `${document.getElementById("statusIndices").textContent} | ${document.getElementById("statusGrid").textContent}`.replace(/\s+/g, " ").trim(),
      canvasHeight: Math.round(document.getElementById("canvasContainer").getBoundingClientRect().height),
      overflow,
    };
  });
}

try {
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await mobile.goto(origin, { waitUntil: "load" });
  await mobile.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await freeze(mobile);
  const start = await snapshot(mobile);
  await mobile.screenshot({ path: path.join(usability, "mobile-start-scan.png") });

  await mobile.selectOption("#traceSelect", "1");
  await mobile.click("#loadBtn");
  await mobile.waitForSelector("#traceLoadingHud.visible");
  await mobile.waitForTimeout(200);
  const loading = await snapshot(mobile);
  await mobile.screenshot({ path: path.join(usability, "mobile-sidebar-loading-live.png") });

  pendingTrace.writeHead(200, { "Content-Type": "application/x-ndjson" });
  pendingTrace.write(headerLine);
  await mobile.waitForFunction(() => document.body.classList.contains("playback-ready"));
  await mobile.waitForTimeout(200);
  const ready = await snapshot(mobile);

  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  pendingTrace = null;
  await desktop.goto(origin, { waitUntil: "load" });
  await desktop.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await freeze(desktop);
  await desktop.selectOption("#traceSelect", "1");
  await desktop.click("#loadBtn");
  await desktop.waitForSelector("#traceLoadingHud.visible");
  await desktop.waitForTimeout(200);
  const desktopLoading = await snapshot(desktop);

  console.log(JSON.stringify({ start, loading, ready, desktopLoading }, null, 2));
} finally {
  await browser.close();
  server.close();
}

import { chromium } from "playwright-core";
import { pathToFileURL } from "node:url";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
const headerLine = JSON.stringify({
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 10,
  r_val: 20,
  expected_frechet: 1.2,
  bbox: [0, 0, 100, 100],
  stream: [[0, 0], [10, 10], [20, 5]],
}) + "\n";
let pendingTrace = null;
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 12, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    pendingTrace = res;
    return;
  }
  const filePath = url.pathname === "/" ? path.join(root, "index.html") : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); res.end("not found"); return; }
    const type = filePath.endsWith(".js") ? "text/javascript" : "text/html";
    res.writeHead(200, { "Content-Type": type });
    res.end(data);
  });
});
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });
try {
  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await desktop.goto(origin, { waitUntil: "load" });
  await desktop.screenshot({ path: "/tmp/pwshot/desktop-empty.png" });

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await mobile.goto(origin, { waitUntil: "load" });
  await mobile.waitForFunction(() => document.querySelectorAll("#traceSelect option").length > 1);
  await mobile.selectOption("#traceSelect", "1");
  await mobile.click("#loadBtn");
  await mobile.waitForSelector("#traceLoadingHud.visible");
  pendingTrace.writeHead(200, { "Content-Type": "application/x-ndjson" });
  pendingTrace.write(headerLine);
  await mobile.waitForFunction(() => document.body.classList.contains("playback-ready"));
  await mobile.waitForTimeout(200);
  await mobile.screenshot({ path: "/tmp/pwshot/mobile-ready.png", fullPage: true });

  const findings = await mobile.evaluate(() => {
    const issues = [];
    const title = document.querySelector("header h1");
    const tr = title.getBoundingClientRect();
    const back = document.querySelector(".mobile-back").getBoundingClientRect();
    if (tr.left < back.right - 4) issues.push("title overlaps back");
    if (title.scrollWidth > title.clientWidth + 1) issues.push(`title clipped ${title.scrollWidth} vs ${title.clientWidth}`);
    const params = document.getElementById("paramsBar").getBoundingClientRect();
    issues.push(`params left ${Math.round(params.left)} top ${Math.round(params.top)}`);
    const play = document.getElementById("mobilePlayBtn");
    const pcs = getComputedStyle(play);
    issues.push(`play disabled ${play.disabled} opacity ${pcs.opacity}`);
    const layers = document.getElementById("layersSection");
    issues.push(`layers open ${layers.classList.contains("layers-open")} height ${Math.round(layers.getBoundingClientRect().height)}`);
    const sidebar = document.getElementById("sidebar");
    issues.push(`sidebar children ${sidebar.children.length} height ${Math.round(sidebar.getBoundingClientRect().height)}`);
    return issues;
  });
  console.log(JSON.stringify(findings, null, 2));
} finally {
  await browser.close();
  server.close();
}
